from urllib.parse import parse_qs, urlparse

import requests

# Ambiente: sandbox por padrão. Produção: https://api.arquivei.com.br
BASE = os.environ.get("QIVE_BASE_URL", "https://sandbox-api.arquivei.com.br")
HEADERS = {
    "X-API-ID": os.environ["QIVE_API_ID"],    # <<SEU_API_ID>>
    "X-API-KEY": os.environ["QIVE_API_KEY"],  # <<SUA_API_KEY>>
    "Content-Type": "application/json",
}


def chamar(metodo, caminho, corpo=None, params=None, tentativas=4):
    """Chama a API da Qive respeitando o 429 (Retry-After) e repetindo erros 5xx."""
    for t in range(tentativas):
        r = requests.request(metodo, BASE + caminho, headers=HEADERS, json=corpo, params=params, timeout=60)
        if r.status_code == 429:
            time.sleep(int(r.headers.get("Retry-After", "5")) + 1)
            continue
        if r.status_code >= 500 and t < tentativas - 1:
            time.sleep(2 ** t)
            continue
        if r.status_code in (401, 403):
            raise RuntimeError("Credenciais recusadas: confira X-API-ID, X-API-KEY e o ambiente (sandbox x producao).")
        if r.status_code >= 400:
            raise RuntimeError(f"Qive respondeu HTTP {r.status_code}: {r.text[:300]}")
        return r.json() if r.content else None
    raise RuntimeError("Limite de requisicoes: tentativas esgotadas.")


def pegar(d, caminho):
    for parte in caminho.split("."):
        d = d.get(parte) if isinstance(d, dict) else None
    return d


def campo_xml(xml_b64, tag):
    """Decodifica o XML (Base64) e devolve o texto do primeiro elemento com o nome pedido (ignora namespace)."""
    from defusedxml import ElementTree as ET  # pip install defusedxml (parser seguro contra XXE)
    raiz = ET.fromstring(base64.b64decode(xml_b64))
    for el in raiz.iter():
        if el.tag.split("}")[-1] == tag:
            return el.text
    return None


def proximo_cursor(resp):
    """page.next pode vir como número ou como URL; nos dois casos devolve o valor do cursor."""
    prox = pegar(resp, "page.next")
    if prox in (None, ""):
        return None
    if isinstance(prox, str) and "cursor=" in prox:
        return parse_qs(urlparse(prox).query).get("cursor", [None])[0]
    return prox


def listar(caminho, ini="2026-09-01", fim="2026-09-30"):
    registros, cursor, vistos = [], 0, set()
    while True:
        params = {"created_at[from]": f"{ini} 00:00:00", "created_at[to]": f"{fim} 23:59:59", "limit": 50}
        params["cursor"] = cursor
        resp = chamar("GET", caminho, params=params) or {}
        lote = resp.get("data") or []
        registros.extend(lote)
        cursor = proximo_cursor(resp)
        if len(lote) < params["limit"] or cursor is None or cursor in vistos:
            break
        vistos.add(cursor)
    return registros


if __name__ == "__main__":
    linhas = listar("/v1/cte/taker")
    print(len(linhas), "documentos")
    if linhas and linhas[0].get("xml"):
        print(base64.b64decode(linhas[0]["xml"])[:200])  # XML do documento

