// Node 18+ (fetch nativo). Ambiente: sandbox por padrão; produção: https://api.arquivei.com.br
const BASE = process.env.QIVE_BASE_URL ?? "https://sandbox-api.arquivei.com.br";
const HEADERS: Record<string, string> = {
  "X-API-ID": process.env.QIVE_API_ID!,   // <<SEU_API_ID>>
  "X-API-KEY": process.env.QIVE_API_KEY!, // <<SUA_API_KEY>>
  "Content-Type": "application/json",
};
const espera = (s: number) => new Promise((r) => setTimeout(r, s * 1000));

async function chamar(metodo: string, caminho: string, corpo?: unknown, params?: URLSearchParams): Promise<any> {
  const url = BASE + caminho + (params && params.toString() ? `?${params}` : "");
  for (let t = 0; t < 4; t++) {
    const r = await fetch(url, { method: metodo, headers: HEADERS, body: corpo === undefined ? undefined : JSON.stringify(corpo) });
    if (r.status === 429) { await espera(Number(r.headers.get("Retry-After") ?? 5) + 1); continue; }
    if (r.status >= 500 && t < 3) { await espera(2 ** t); continue; }
    if (r.status === 401 || r.status === 403) throw new Error("Credenciais recusadas: confira X-API-ID, X-API-KEY e o ambiente.");
    if (!r.ok) throw new Error(`Qive respondeu HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
    return r.status === 204 ? null : r.json();
  }
  throw new Error("Limite de requisições: tentativas esgotadas.");
}

